function Cli([string]$name,[string]$command,[int]$seconds=15){
 PublicPrincipal
 $cp117LaunchingIdentity=[Security.Principal.WindowsIdentity]::GetCurrent();$cp117LaunchingSession=(Get-Process -Id $PID).SessionId
 if($deadline.Elapsed.TotalSeconds -gt 600){throw 'PUBLIC_FLOW_BUDGET'}
 if($name -notmatch '^[a-z0-9-]{1,40}$' -or $seconds -notin @(15,120) -or $command -notmatch '^(status|quit|settings show|subscriptions list|routing show|locations list|ssh key status|updates (status|check)|--async updates (download|install)|operations status [0-9a-f-]{36})$'){throw 'PUBLIC_COMMAND_CATALOGUE'}
 $script:sequence++;if($script:sequence -gt 640){throw 'PUBLIC_CALL_COUNT'};$prefix=$name+'-'+$script:sequence
 $ownerArguments='';if($null -ne $script:controller){if($script:controller -notmatch '^[0-9a-f-]{36}$' -or $script:revision -lt 0){throw 'PUBLIC_OWNER_ARGUMENT'};$ownerArguments=' --controller-id '+$script:controller+' --if-revision '+$script:revision}
 $info=[Diagnostics.ProcessStartInfo]::new($cli,'--state-dir "'+$state+'" --json --timeout-seconds '+$seconds+$ownerArguments+' '+$command);$info.UseShellExecute=$false;$info.CreateNoWindow=$true;$info.RedirectStandardOutput=$true;$info.RedirectStandardError=$true
 $child=[Diagnostics.Process]::new();$child.StartInfo=$info;$started=$false;$out=$null;$err=$null;$birth=$null;$completed=$false;$exit=$null;$outFile=$null;$errFile=$null;$childFile=$null;$collectionFile=$null;$errorFile=$null
 try{
  $outFile=OpenRaw ($prefix+'.stdout.private');$errFile=OpenRaw ($prefix+'.stderr.private');$childFile=OpenRaw ($prefix+'.child.json');$collectionFile=OpenRaw ($prefix+'.collection.json');$errorFile=OpenRaw ($prefix+'.error.json')
  if(-not $child.Start()){throw 'PUBLIC_CHILD_START'};$started=$true;$script:activePublicChild=$child;$script:activePublicChildRecord=$prefix;$script:activePublicChildBirth=$null
  $out=[Cp117StdinCapture]::new($child.StandardOutput.BaseStream,16384);$err=[Cp117StdinCapture]::new($child.StandardError.BaseStream,16384)
  $birth=$child.StartTime.ToUniversalTime().ToFileTimeUtc().ToString();$script:activePublicChildBirth=$birth
  JsonHeld $childFile @{pid=$child.Id;birth=$birth;phase=$phase;command=$command;securityScope='launching-task';launchingPrincipalSid=$cp117LaunchingIdentity.User.Value;launchingSessionId=$cp117LaunchingSession;launchingTaskRunLevel='Limited';childTokenObserved=$false;tokenLimited=$null}
  $completed=$child.WaitForExit(($seconds+5)*1000)
  if($completed){$exit=[int]$child.ExitCode;$outJoined=$out.Join(2000);$errJoined=$err.Join(2000)}
  [byte[]]$stdout=@($out.Snapshot());[byte[]]$stderr=@($err.Snapshot())
  WriteHeld $outFile $stdout;WriteHeld $errFile $stderr
  JsonHeld $collectionFile @{pid=$child.Id;birth=$birth;completed=$completed;exitCode=$exit;stdoutEof=$out.Eof;stderrEof=$err.Eof;stdoutOverflow=$out.Overflow;stderrOverflow=$err.Overflow;stdoutError=$out.Error;stderrError=$err.Error;stdoutBytes=$stdout.Length;stderrBytes=$stderr.Length}
  if(-not $completed -or -not $outJoined -or -not $errJoined -or -not $out.Eof -or -not $err.Eof -or $out.Overflow -or $err.Overflow -or $null -ne $out.Error -or $null -ne $err.Error){throw 'PUBLIC_CHILD_UNKNOWN'}
  $value=ConvertFrom-Json -InputObject ([Text.UTF8Encoding]::new($false,$true).GetString($stdout))
  if(($value.schemaVersion -isnot [int] -and $value.schemaVersion -isnot [long]) -or $value.schemaVersion -ne 1 -or $value.ok -isnot [bool] -or $value.final -isnot [bool] -or ($value.configurationRevision -isnot [int] -and $value.configurationRevision -isnot [long]) -or $value.configurationRevision -lt 0 -or $stderr.Length -ne 0){throw 'PUBLIC_ENVELOPE'}
  $notReady=($name -in @('initial-status','post-status') -and $command -ceq 'status' -and $value.ok -eq $false -and $value.final -eq $true -and $value.code -cin @('UNAVAILABLE','NOT_FOUND') -and $null -eq $value.controllerId -and $exit -ne 0)
  if(-not $notReady -and $value.controllerId -notmatch '^[0-9a-f-]{36}$'){throw 'PUBLIC_ENVELOPE_OWNER'}
  return [pscustomobject]@{notReady=$notReady;value=$value;exitCode=$exit;record=$prefix}
 }catch{
  $primary=$_
  if($started){
   try{if($null -eq $out){$out=[Cp117StdinCapture]::new($child.StandardOutput.BaseStream,16384)}}catch{}
   try{if($null -eq $err){$err=[Cp117StdinCapture]::new($child.StandardError.BaseStream,16384)}}catch{}
   try{$completed=$child.WaitForExit(0);if($completed){$exit=[int]$child.ExitCode;if($null -ne $out){$null=$out.Join(1000)};if($null -ne $err){$null=$err.Join(1000)}}}catch{}
   try{if($null -ne $out){WriteHeld $outFile ([byte[]]@($out.Snapshot()))}}catch{}
   try{if($null -ne $err){WriteHeld $errFile ([byte[]]@($err.Snapshot()))}}catch{}
   try{JsonHeld $childFile @{pid=$child.Id;birth=$birth;phase=$phase;command=$command;identityKnown=($null -ne $birth);outcome='unknown'}}catch{}
   try{JsonHeld $collectionFile @{pid=$child.Id;birth=$birth;completed=$completed;exitCode=$exit;stdoutEof=$(if($null -ne $out){$out.Eof}else{$false});stderrEof=$(if($null -ne $err){$err.Eof}else{$false});stdoutCaptureKnown=($null -ne $out);stderrCaptureKnown=($null -ne $err);outcome='unknown';replayAllowed=$false}}catch{}
  }
  try{JsonHeld $errorFile @{phase=$phase;pid=$(if($started){$child.Id}else{$null});birth=$birth;completed=$completed;exitCode=$exit;exceptionType=$primary.Exception.GetType().FullName;hresult=$primary.Exception.HResult;outcome='unknown';replayAllowed=$false}}catch{}
  throw $primary
 }finally{foreach($file in @($outFile,$errFile,$childFile,$collectionFile,$errorFile)){if($null -ne $file){$file.Dispose()}};if($completed){$child.Dispose()}}

}
